<script setup>import {computed} from 'vue';const props=defineProps({value:Number,label:{type:String,default:'完成进度'}});const safe=computed(()=>Math.max(0,Math.min(100,props.value||0)))</script><template><div class="progress"><div class="progress-label"><span>{{label}}</span><b>{{safe}}%</b></div><div class="track"><div class="fill" :style="{width:safe+'%'}"></div></div></div></template>